241	    public void saveOwner(Owner owner) throws DataAccessException {
242	        if (owner.isNew()) {
243	            if (owner.getCustomerCode() == null) {
244	                owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
245	            }
246	            if (owner.getNamesakeCount() == null) {
247	                owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
248	            }
249	        }
250	        ownerRepository.save(owner);
251	
252	    }
