254	    /**
255	     * Count the existing owners (before this create) that share the given first and last name,
256	     * compared case-insensitively, as required by the read-only {@code namesakeCount} field.
257	     */
258	    private int countNamesakes(String firstName, String lastName) {
259	        if (firstName == null || lastName == null) {
260	            return 0;
261	        }
262	        return (int) ownerRepository.findAll().stream()
263	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
264	                && lastName.equalsIgnoreCase(owner.getLastName()))
265	            .count();
266	    }
267	
268	    /**
269	     * Build a customer code formatted {@code '<CITY3>-<LAST3>-<NNNN>'}, where {@code CITY3}
270	     * is the upper-cased first three letters of the owner's city, {@code LAST3} the
271	     * upper-cased first three letters of the owner's last name and {@code NNNN} a per-city,
272	     * 4-digit zero-padded sequence equal to one more than the current number of owners
273	     * already in that city (e.g. {@code 'LON-SMI-0007'}).
274	     */
275	    private String generateCustomerCode(String city, String lastName) {
276	        String cityName = city == null ? "" : city;
277	        String city3 = cityName.substring(0, Math.min(3, cityName.length())).toUpperCase();
278	        String name = lastName == null ? "" : lastName;
279	        String last3 = name.substring(0, Math.min(3, name.length())).toUpperCase();
280	        long sequence = countOwnersInCity(cityName) + 1L;
281	        return String.format("%s-%s-%04d", city3, last3, sequence);
282	    }
283	
284	    /**
285	     * Count the existing owners whose city matches the given city, compared case-insensitively,
286	     * used to derive the per-city sequence of the customer code.
287	     */
288	    private long countOwnersInCity(String city) {
289	        if (city == null) {
290	            return 0L;
291	        }
292	        return ownerRepository.findAll().stream()
293	            .filter(owner -> city.equalsIgnoreCase(owner.getCity()))
294	            .count();
295	    }
