300	        String normalized = normalizeTelephone(telephone);
301	        if (normalized == null) {
302	            return false;
303	        }
304	        return ownerRepository.findAll().stream()
305	            .map(owner -> normalizeTelephone(owner.getTelephone()))
306	            .anyMatch(normalized::equals);
307	    }
